@props(['name', 'label', 'value' => null, 'required' => false, 'id' => null])
@php($inputId = $id ?? $name)
<div x-data="staffSearch" class="relative" @click.outside="open = false"><label for="{{ $inputId }}">{{ $label }} @if($required)<span class="required-mark">*</span>@endif</label><input class="input" type="text" name="{{ $name }}" id="{{ $inputId }}" value="{{ $value }}" @input.debounce.350ms="search($event.target.value)" @keydown.escape="open = false" @keydown.arrow-down.prevent="$refs.results?.querySelector('button')?.focus()" @if($required) required @endif maxlength="255" autocomplete="off" aria-autocomplete="list" :aria-expanded="open" placeholder="Type a name to search…">
    <div x-cloak x-show="open" class="autocomplete" x-ref="results"><template x-for="(person, index) in results" :key="person.account_name"><button type="button" @click="choose(person)" @keydown.arrow-down.prevent="$el.nextElementSibling?.focus()" @keydown.arrow-up.prevent="$el.previousElementSibling?.focus()"><strong x-text="person.name"></strong><small x-text="person.account_name"></small></button></template><p x-show="!results.length" x-text="message"></p></div><small class="field-help">You can also enter the full name manually.</small></div>
